  FROM (VALUES
    ('56782417-5d5c-4372-83b2-353176ef4f0e'::uuid, 'f02bcf78-78dd-4d45-bdcf-a8a9033e3c05'::uuid, 'Council Member (District 1)', false, 'bd9189dc-3b01-4516-a651-73ccce15e898'::uuid),
