-- ─── 0. Pre-flight: every binding target exists ───────────────────────────────────────
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM (VALUES
    ('0622230', 'LOCAL_EXEC', 'Mayor', 'El Monte Mayor'),
    ('el-monte-council-district-2', 'LOCAL', NULL, 'El Monte City Council District 2'),
    ('el-monte-council-district-3', 'LOCAL', NULL, 'El Monte City Council District 3'),
    ('el-monte-council-district-6', 'LOCAL', NULL, 'El Monte City Council District 6'),
    ('0622230', 'LOCAL_EXEC', 'City Clerk', 'El Monte City Clerk'),
    ('0622230', 'LOCAL_EXEC', 'City Treasurer', 'El Monte City Treasurer'),
    ('glendora-council-district-1', 'LOCAL', NULL, 'Glendora City Council District 1'),
    ('glendora-council-district-4', 'LOCAL', NULL, 'Glendora City Council District 4'),
    ('diamond-bar-council-district-1', 'LOCAL', NULL, 'Diamond Bar City Council District 1'),
    ('diamond-bar-council-district-3', 'LOCAL', NULL, 'Diamond Bar City Council District 3'),
    ('diamond-bar-council-district-4', 'LOCAL', NULL, 'Diamond Bar City Council District 4'),
    ('claremont-council-district-2', 'LOCAL', NULL, 'Claremont City Council District 2'),
    ('claremont-council-district-3', 'LOCAL', NULL, 'Claremont City Council District 3'),
    ('claremont-council-district-4', 'LOCAL', NULL, 'Claremont City Council District 4'),
    ('la-verne-council-district-1', 'LOCAL', NULL, 'La Verne City Council District 1'),
    ('la-verne-council-district-3', 'LOCAL', NULL, 'La Verne City Council District 3'),
    ('la-verne-council-district-4', 'LOCAL', NULL, 'La Verne City Council District 4')
  ) AS v(place, dtype, otitle, pos)
   WHERE NOT EXISTS (SELECT 1 FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id
                      WHERE d.geo_id = v.place AND d.district_type = v.dtype AND (v.otitle IS NULL OR o.title = v.otitle));
  IF n <> 0 THEN RAISE EXCEPTION 'pre-flight: % race(s) with no office to bind to', n; END IF;
END $$;

-- ─── 1. Races ─────────────────────────────────────────────────────────────────────────
INSERT INTO essentials.races (election_id, office_id, position_name, primary_party, seats)
SELECT 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid, t.office_id, t.pos, NULL, t.seats
  FROM (SELECT v.pos, v.seats,
               (SELECT o.id FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id
                 WHERE d.geo_id = v.place AND d.district_type = v.dtype AND (v.otitle IS NULL OR o.title = v.otitle)
                 ORDER BY o.id LIMIT 1) AS office_id
          FROM (VALUES
    ('0622230', 'LOCAL_EXEC', 'Mayor', 'El Monte Mayor', 1),
    ('el-monte-council-district-2', 'LOCAL', NULL, 'El Monte City Council District 2', 1),
    ('el-monte-council-district-3', 'LOCAL', NULL, 'El Monte City Council District 3', 1),
    ('el-monte-council-district-6', 'LOCAL', NULL, 'El Monte City Council District 6', 1),
    ('0622230', 'LOCAL_EXEC', 'City Clerk', 'El Monte City Clerk', 1),
    ('0622230', 'LOCAL_EXEC', 'City Treasurer', 'El Monte City Treasurer', 1),
    ('glendora-council-district-1', 'LOCAL', NULL, 'Glendora City Council District 1', 1),
    ('glendora-council-district-4', 'LOCAL', NULL, 'Glendora City Council District 4', 1),
    ('diamond-bar-council-district-1', 'LOCAL', NULL, 'Diamond Bar City Council District 1', 1),
    ('diamond-bar-council-district-3', 'LOCAL', NULL, 'Diamond Bar City Council District 3', 1),
    ('diamond-bar-council-district-4', 'LOCAL', NULL, 'Diamond Bar City Council District 4', 1),
    ('claremont-council-district-2', 'LOCAL', NULL, 'Claremont City Council District 2', 1),
    ('claremont-council-district-3', 'LOCAL', NULL, 'Claremont City Council District 3', 1),
    ('claremont-council-district-4', 'LOCAL', NULL, 'Claremont City Council District 4', 1),
