-- ─── 3. Antipartisan: clear the stored party on every linked candidate row ──────────
UPDATE essentials.politicians SET party = NULL
 WHERE party IS NOT NULL AND id IN ('0738714b-e2e0-42d6-b594-2edfa28736b5', '18dbc5bc-999e-4e75-b602-80c0ca8202ee', '37cd6b22-0669-4c48-995e-7a97aa20a68a', '4a500ae5-3bdd-4a1d-897c-51ab28840489', '4cdfe715-5128-49cd-a88c-9b4f35f63653', '5ef91cd1-aacf-4bae-8476-5c180606802d', '97fe17c8-83b4-4ce6-b5a7-5265eb6ac5e7', 'a1898bc3-7c48-4520-a4be-9a62bac73980', 'a5e2f51c-b87e-4f0b-bd45-01493876591f', 'aecc3037-963f-428a-b7cf-fe0cde67142e', 'b9149eb5-4dc6-400e-b685-92ad0fa05b18', 'c7f76380-249c-436b-824c-ba44ff496c40', 'd9e807c6-7266-4fdc-94d8-617a6c74586a', 'e39b0a67-2447-4d25-b207-6a6c20307d94', 'e562016e-d672-4e8a-a870-c0de2cbff0f5', 'f34cded6-da16-4ce7-aed9-e5ef2b905108');

-- ─── 4. Post-verify gate ──────────────────────────────────────────────────────────────
DO $$
DECLARE
  pos text[] := ARRAY['El Monte Mayor', 'El Monte City Council District 2', 'El Monte City Council District 3', 'El Monte City Council District 6', 'El Monte City Clerk', 'El Monte City Treasurer', 'Glendora City Council District 1', 'Glendora City Council District 4', 'Diamond Bar City Council District 1', 'Diamond Bar City Council District 3', 'Diamond Bar City Council District 4', 'Claremont City Council District 2', 'Claremont City Council District 3', 'Claremont City Council District 4', 'La Verne City Council District 1', 'La Verne City Council District 3', 'La Verne City Council District 4'];
  n_races int; n_cands int; n_null int; n_party int; n_badcount int; n_inc int; n_badinc int; n_extralink int; n_linked int; n_incseat int;
  n_overinc int; n_unreach int; n_pparty int; n_dpoly int; n_seatok int; n_dbad int; n_size int; n_dleak int; n_em int;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE r.office_id IS NULL), count(*) FILTER (WHERE r.primary_party IS NOT NULL)
    INTO n_races, n_null, n_party FROM essentials.races r WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos);
  SELECT count(*) INTO n_cands FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos);
  -- each race carries exactly the clerk's field, on the expected seat count
  SELECT count(*) INTO n_badcount FROM (VALUES
      ('El Monte Mayor', 1, 3, 1),
      ('El Monte City Council District 2', 1, 1, 1),
      ('El Monte City Council District 3', 1, 1, 1),
      ('El Monte City Council District 6', 1, 2, 1),
      ('El Monte City Clerk', 1, 2, 1),
      ('El Monte City Treasurer', 1, 3, 0),
      ('Glendora City Council District 1', 1, 2, 1),
      ('Glendora City Council District 4', 1, 3, 1),
      ('Diamond Bar City Council District 1', 1, 2, 1),
      ('Diamond Bar City Council District 3', 1, 1, 1),
      ('Diamond Bar City Council District 4', 1, 2, 1),
      ('Claremont City Council District 2', 1, 1, 1),
      ('Claremont City Council District 3', 1, 2, 1),
      ('Claremont City Council District 4', 1, 3, 0),
      ('La Verne City Council District 1', 1, 2, 1),
      ('La Verne City Council District 3', 1, 2, 1),
      ('La Verne City Council District 4', 1, 1, 1)
    ) AS v(pos, seats, n_cand, n_inc)
    LEFT JOIN essentials.races r ON r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = v.pos
   WHERE r.id IS NULL OR r.seats <> v.seats
      OR (SELECT count(*) FROM essentials.race_candidates rc WHERE rc.race_id = r.id) <> v.n_cand
      OR (SELECT count(*) FROM essentials.race_candidates rc WHERE rc.race_id = r.id AND rc.is_incumbent) <> v.n_inc;
  -- incumbents: linked, and holding THIS race's own seat (for a district race: that district's office)
  -- any linked candidate (incl. a sitting official running for another seat): a current holder somewhere in the city
  SELECT count(*) FILTER (WHERE rc.is_incumbent),
         count(*) FILTER (WHERE rc.is_incumbent AND rc.politician_id IS NULL),
         count(*) FILTER (WHERE rc.politician_id IS NOT NULL AND NOT EXISTS (
           SELECT 1 FROM essentials.office_current_holder och JOIN essentials.offices o2 ON o2.id = och.office_id
             JOIN essentials.districts d2 ON d2.id = o2.district_id
            WHERE och.politician_id = rc.politician_id
              AND (d2.geo_id = cm.place OR (cm.pat <> '' AND d2.geo_id LIKE cm.pat)
                   OR d2.geo_id = (SELECT d.geo_id FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id WHERE o.id = r.office_id)))),
         count(*) FILTER (WHERE rc.politician_id IS NOT NULL),
         count(*) FILTER (WHERE rc.is_incumbent AND rc.politician_id IS NOT NULL AND NOT EXISTS (
           SELECT 1 FROM essentials.office_current_holder och JOIN essentials.offices o2 ON o2.id = och.office_id
             JOIN essentials.districts d2 ON d2.id = o2.district_id
            WHERE och.politician_id = rc.politician_id
              AND d2.geo_id = (SELECT d.geo_id FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id WHERE o.id = r.office_id)))
    INTO n_inc, n_badinc, n_extralink, n_linked, n_incseat
    FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
    JOIN (VALUES
      ('El Monte Mayor', '0622230', 'el-monte-council-district-%'),
      ('El Monte City Council District 2', '0622230', 'el-monte-council-district-%'),
      ('El Monte City Council District 3', '0622230', 'el-monte-council-district-%'),
      ('El Monte City Council District 6', '0622230', 'el-monte-council-district-%'),
      ('El Monte City Clerk', '0622230', 'el-monte-council-district-%'),
      ('El Monte City Treasurer', '0622230', 'el-monte-council-district-%'),
      ('Glendora City Council District 1', '0630014', 'glendora-council-district-%'),
      ('Glendora City Council District 4', '0630014', 'glendora-council-district-%'),
      ('Diamond Bar City Council District 1', '0619192', 'diamond-bar-council-district-%'),
      ('Diamond Bar City Council District 3', '0619192', 'diamond-bar-council-district-%'),
      ('Diamond Bar City Council District 4', '0619192', 'diamond-bar-council-district-%'),
      ('Claremont City Council District 2', '0613756', 'claremont-council-district-%'),
      ('Claremont City Council District 3', '0613756', 'claremont-council-district-%'),
      ('Claremont City Council District 4', '0613756', 'claremont-council-district-%'),
      ('La Verne City Council District 1', '0640830', 'la-verne-council-district-%'),
      ('La Verne City Council District 3', '0640830', 'la-verne-council-district-%'),
      ('La Verne City Council District 4', '0640830', 'la-verne-council-district-%')
    ) AS cm(cpos, place, pat) ON cm.cpos = r.position_name
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos);
  SELECT count(*) INTO n_overinc FROM essentials.races r WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos)
     AND (SELECT count(*) FROM essentials.race_candidates rc WHERE rc.race_id = r.id AND rc.is_incumbent) > r.seats;
  -- END TO END: an interior point of each race's own polygon reaches that race
  SELECT count(*) INTO n_unreach FROM essentials.races r
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
    JOIN essentials.geofence_boundaries me ON me.geo_id = d.geo_id AND me.mtfcc = d.mtfcc
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos)
     AND NOT EXISTS (SELECT 1 FROM essentials.geofence_boundaries gb
                      WHERE gb.geo_id = d.geo_id AND (d.mtfcc IS NULL OR gb.mtfcc = d.mtfcc)
                        AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(me.geometry)));
  SELECT count(*) INTO n_pparty FROM essentials.politicians p WHERE p.party IS NOT NULL AND p.id IN (
    SELECT rc.politician_id FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
     WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos) AND rc.politician_id IS NOT NULL);
  IF n_races <> 17 THEN RAISE EXCEPTION 'expected 17 races, got %', n_races; END IF;
  IF n_cands <> 33 THEN RAISE EXCEPTION 'expected 33 candidates, got %', n_cands; END IF;
  IF n_null <> 0 OR n_party <> 0 THEN RAISE EXCEPTION 'office-less (%) or partisan (%) race', n_null, n_party; END IF;
  IF n_badcount <> 0 THEN RAISE EXCEPTION '% race(s) whose seats / candidates / incumbents differ from the clerk list', n_badcount; END IF;
  IF n_inc <> 15 THEN RAISE EXCEPTION 'expected 15 incumbents, got %', n_inc; END IF;
  IF n_badinc <> 0 THEN RAISE EXCEPTION '% incumbent(s) left unlinked', n_badinc; END IF;
  IF n_extralink <> 0 THEN RAISE EXCEPTION '% linked candidate(s) are not a current holder in their city', n_extralink; END IF;
  IF n_linked <> 16 THEN RAISE EXCEPTION 'expected 16 linked candidates, got %', n_linked; END IF;
  IF n_incseat <> 0 THEN RAISE EXCEPTION '% incumbent(s) do not hold the seat their race is for', n_incseat; END IF;
  IF n_overinc <> 0 THEN RAISE EXCEPTION '% race(s) with more incumbents than seats', n_overinc; END IF;
  IF n_unreach <> 0 THEN RAISE EXCEPTION '% race(s) not reached from inside their own city', n_unreach; END IF;
  IF n_pparty <> 0 THEN RAISE EXCEPTION '% linked candidate row(s) still carry a party', n_pparty; END IF;
  -- every new district row resolves to its polygon
  SELECT count(*) INTO n_dpoly FROM essentials.districts d JOIN essentials.geofence_boundaries gb ON gb.geo_id = d.geo_id AND gb.mtfcc = d.mtfcc
   WHERE d.district_type = 'LOCAL' AND d.id IN ('1ce59260-e196-4948-8541-d71070f60d21', '09125d15-574b-4dfe-8013-0a3c67a323e6', '318acfbb-5374-40e3-8adb-8070c88fd174', '984372a0-0321-4aca-8425-8d778e293a62', '7a98abb0-380b-41d5-9270-a43e29c892f6', '0d982302-23e8-43bf-a6d1-46cef6d48cb7', 'c213f5fa-37d9-4218-88b2-de4b8b5ac116', '47afd81d-efe4-435f-b1ab-c5c8f1672359', '1d9e93b4-e4cb-452f-a876-3cfdc9ea9f86', 'f3cb2128-612b-4fb0-8813-47d0abbf7cb3', '1043cb7c-994a-409e-a20e-5ae48728f6cd', 'f02bcf78-78dd-4d45-bdcf-a8a9033e3c05', '7fe2c27b-5882-41ac-9910-931ef78eb311', 'e48c39ee-7140-4e4e-94e3-c57662e42060', 'bae6b2c8-7f7e-4349-8837-e0df358ef8dd', 'fd628c55-a20e-4599-b865-83f4d4f806f8', '363cc505-2589-40de-ac7d-d41859f84f13', '61daa214-1b8a-4d36-b6c2-a391b6e129e5', 'e558efce-b5b1-433e-87e3-086f66ec2456', '1e374e26-6e74-4e76-b0a4-6e4e3e49dc4b', 'f6381ce1-fb7a-4a34-870a-11f3f4ff5cce', '76afa365-d531-4ae3-aa1b-c0b8bdebab64', '0769e263-f3a4-49b4-aacb-bff95cff8b9d', '00a53bf1-fcc5-479b-bd52-e99735b3983e', '651a3d97-9ed9-4449-9e52-51ef1f4ad8c8', 'ae25705f-5fbd-4777-87f8-2e3b739cd1d9');
  -- every seat sits where it should, with its title, held by the named member (or flagged vacant)
  SELECT count(*) INTO n_seatok FROM (VALUES
      ('211af77a-4c4f-4f5b-b604-3bd99b57210f'::uuid, 'bb21e688-3264-4237-beda-e748db65384a'::uuid, 'el-monte-council-district-1', 'Council Member (District 1)'),
      ('7e9eac5e-ffd7-4a6a-a417-01e3607b733d'::uuid, 'e39b0a67-2447-4d25-b207-6a6c20307d94'::uuid, 'el-monte-council-district-2', 'Council Member (District 2)'),
      ('06d458fe-8cef-481f-bf6c-ece8fed8df29'::uuid, '0738714b-e2e0-42d6-b594-2edfa28736b5'::uuid, 'el-monte-council-district-3', 'Council Member (District 3)'),
      ('3040818a-533a-4f59-85a5-6bbcdf3d42a9'::uuid, '18dbc5bc-999e-4e75-b602-80c0ca8202ee'::uuid, 'el-monte-council-district-4', 'Council Member (District 4)'),
      ('3ffcb893-5924-47f6-b861-9eda1ac18f25'::uuid, 'f034f7ef-2aef-43fa-8d06-1f6902705dc4'::uuid, 'el-monte-council-district-5', 'Council Member (District 5)'),
      ('ecafba9a-b3a4-4e6b-b74a-4e721854c713'::uuid, 'aecc3037-963f-428a-b7cf-fe0cde67142e'::uuid, 'el-monte-council-district-6', 'Council Member (District 6)'),
      ('317f7354-429a-464a-9332-b3433f20996e'::uuid, '97fe17c8-83b4-4ce6-b5a7-5265eb6ac5e7'::uuid, 'glendora-council-district-1', 'Council Member (District 1)'),
      ('7f4c9c72-cef1-444a-8fe4-6f741b91251d'::uuid, 'acc990ea-5264-4d2f-9e44-940a85105481'::uuid, 'glendora-council-district-2', 'Council Member (District 2)'),
      ('7f12dee9-7a26-4ecb-8e3c-9c0f1f22274e'::uuid, '09b98050-abe0-4c49-8f15-c22e54f5cb78'::uuid, 'glendora-council-district-3', 'Council Member (District 3)'),
      ('605037e7-bcf1-4770-ade5-a30f2c8a0642'::uuid, 'b9149eb5-4dc6-400e-b685-92ad0fa05b18'::uuid, 'glendora-council-district-4', 'Council Member (District 4)'),
      ('cdd860e2-2add-47a4-8219-fed7716d8af1'::uuid, '7ec1b8a2-d0e6-45cc-9af1-17c578f22540'::uuid, 'glendora-council-district-5', 'Council Member (District 5)'),
      ('56782417-5d5c-4372-83b2-353176ef4f0e'::uuid, 'a1898bc3-7c48-4520-a4be-9a62bac73980'::uuid, 'diamond-bar-council-district-1', 'Council Member (District 1)'),
      ('bd9189dc-3b01-4516-a651-73ccce15e898'::uuid, '7e77b904-6fb5-41ec-b82f-e4de16bf3807'::uuid, 'diamond-bar-council-district-2', 'Council Member (District 2)'),
      ('e647c5ec-6bd6-4573-ac3a-6bf7a322c97d'::uuid, 'f34cded6-da16-4ce7-aed9-e5ef2b905108'::uuid, 'diamond-bar-council-district-3', 'Council Member (District 3)'),
      ('168bbdc6-bdf7-4cdb-9f4c-e5d00461473c'::uuid, '4cdfe715-5128-49cd-a88c-9b4f35f63653'::uuid, 'diamond-bar-council-district-4', 'Council Member (District 4)'),
      ('e608221a-5065-4d24-b0c1-ea8c5974500f'::uuid, '71acf86b-dbef-4ff9-85a9-310f05c5c896'::uuid, 'diamond-bar-council-district-5', 'Council Member (District 5)'),
      ('20bc5011-4f87-43ee-93f3-6198a51c885b'::uuid, '556e4303-9d45-4540-8bba-617da6641bfe'::uuid, 'claremont-council-district-1', 'Council Member (District 1)'),
      ('dbdb7b25-52f9-452d-96f8-f1bdcd092e1a'::uuid, 'a5e2f51c-b87e-4f0b-bd45-01493876591f'::uuid, 'claremont-council-district-2', 'Council Member (District 2)'),
      ('7dbf0d57-e8ec-466e-a5a8-a4416d81c428'::uuid, '37cd6b22-0669-4c48-995e-7a97aa20a68a'::uuid, 'claremont-council-district-3', 'Council Member (District 3)'),
      ('afe44025-b315-4480-8725-48d4881f065e'::uuid, 'da8e58bc-7a02-41ed-a8c6-7d7ad087c7b3'::uuid, 'claremont-council-district-4', 'Council Member (District 4)'),
      ('99240d90-b12f-4656-8f22-5a0848fee6c0'::uuid, '3aedc075-d219-40f9-932b-c92d000c5d9a'::uuid, 'claremont-council-district-5', 'Council Member (District 5)'),
      ('41fca131-3e27-408c-95a0-dbda18504698'::uuid, '5ef91cd1-aacf-4bae-8476-5c180606802d'::uuid, 'la-verne-council-district-1', 'Council Member (District 1)'),
      ('4afd9c82-9d26-4362-af68-1227d149ef8b'::uuid, '64d469a4-1f9b-48cd-930d-0947f33cae90'::uuid, 'la-verne-council-district-2', 'Council Member (District 2)'),
      ('94eb5e7b-d4ef-4f06-959f-972f79e362e5'::uuid, 'd9e807c6-7266-4fdc-94d8-617a6c74586a'::uuid, 'la-verne-council-district-3', 'Council Member (District 3)'),
      ('ea28aef2-34b9-487e-9f44-adf808851d9e'::uuid, 'e562016e-d672-4e8a-a870-c0de2cbff0f5'::uuid, 'la-verne-council-district-4', 'Council Member (District 4)'),
      ('01971dff-390d-4219-a5c9-8824a10c9698'::uuid, '2c036cbd-691d-4e4e-adf4-5e0718e17439'::uuid, 'la-verne-council-district-5', 'Council Member (District 5)')
    ) AS v(oid, pid, dgeo, title)
    JOIN essentials.offices o ON o.id = v.oid AND o.title = v.title
    JOIN essentials.districts d ON d.id = o.district_id
    LEFT JOIN essentials.office_current_holder och ON och.office_id = o.id
   WHERE (v.dgeo IS NULL OR d.geo_id = v.dgeo)
     AND ((v.pid IS NOT NULL AND och.politician_id = v.pid) OR (v.pid IS NULL AND och.politician_id IS NULL AND o.is_vacant));
  -- each district row carries exactly one office
  SELECT count(*) INTO n_dbad FROM essentials.districts d WHERE d.id IN ('1ce59260-e196-4948-8541-d71070f60d21', '09125d15-574b-4dfe-8013-0a3c67a323e6', '318acfbb-5374-40e3-8adb-8070c88fd174', '984372a0-0321-4aca-8425-8d778e293a62', '7a98abb0-380b-41d5-9270-a43e29c892f6', '0d982302-23e8-43bf-a6d1-46cef6d48cb7', 'c213f5fa-37d9-4218-88b2-de4b8b5ac116', '47afd81d-efe4-435f-b1ab-c5c8f1672359', '1d9e93b4-e4cb-452f-a876-3cfdc9ea9f86', 'f3cb2128-612b-4fb0-8813-47d0abbf7cb3', '1043cb7c-994a-409e-a20e-5ae48728f6cd', 'f02bcf78-78dd-4d45-bdcf-a8a9033e3c05', '7fe2c27b-5882-41ac-9910-931ef78eb311', 'e48c39ee-7140-4e4e-94e3-c57662e42060', 'bae6b2c8-7f7e-4349-8837-e0df358ef8dd', 'fd628c55-a20e-4599-b865-83f4d4f806f8', '363cc505-2589-40de-ac7d-d41859f84f13', '61daa214-1b8a-4d36-b6c2-a391b6e129e5', 'e558efce-b5b1-433e-87e3-086f66ec2456', '1e374e26-6e74-4e76-b0a4-6e4e3e49dc4b', 'f6381ce1-fb7a-4a34-870a-11f3f4ff5cce', '76afa365-d531-4ae3-aa1b-c0b8bdebab64', '0769e263-f3a4-49b4-aacb-bff95cff8b9d', '00a53bf1-fcc5-479b-bd52-e99735b3983e', '651a3d97-9ed9-4449-9e52-51ef1f4ad8c8', 'ae25705f-5fbd-4777-87f8-2e3b739cd1d9')
     AND (SELECT count(*) FROM essentials.offices o WHERE o.district_id = d.id) <> 1;
  -- each council has exactly its expected number of sitting members (place + its districts)
  SELECT count(*) INTO n_size FROM (VALUES
      ('0622230', 'el-monte-council-district-%', 7),
      ('0630014', 'glendora-council-district-%', 5),
      ('0619192', 'diamond-bar-council-district-%', 5),
      ('0613756', 'claremont-council-district-%', 5),
      ('0640830', 'la-verne-council-district-%', 5)
    ) AS v(place, pat, size)
   WHERE (SELECT count(DISTINCT och.politician_id) FROM essentials.districts d JOIN essentials.offices o ON o.district_id = d.id
            JOIN essentials.office_current_holder och ON och.office_id = o.id
           WHERE d.district_type IN ('LOCAL', 'LOCAL_EXEC') AND (d.geo_id = v.place OR d.geo_id LIKE v.pat)
             AND o.title NOT IN ('City Clerk', 'City Treasurer')) = v.size;
  -- NO CROSS-LEAK: an interior point of every district reaches exactly its own district race (if up) or none
  SELECT count(*) INTO n_dleak FROM (
    SELECT a.geo_id, a.up, (SELECT count(*) FROM essentials.races r
        JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
        JOIN essentials.geofence_boundaries gb ON gb.geo_id = d.geo_id AND (d.mtfcc IS NULL OR gb.mtfcc = d.mtfcc)
       WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = ANY (pos) AND r.position_name LIKE '%District%'
         AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(me.geometry))) AS hits
      FROM (VALUES
      ('el-monte-council-district-1', 0),
      ('el-monte-council-district-2', 1),
      ('el-monte-council-district-3', 1),
      ('el-monte-council-district-4', 0),
      ('el-monte-council-district-5', 0),
      ('el-monte-council-district-6', 1),
      ('glendora-council-district-1', 1),
      ('glendora-council-district-2', 0),
      ('glendora-council-district-3', 0),
      ('glendora-council-district-4', 1),
      ('glendora-council-district-5', 0),
      ('diamond-bar-council-district-1', 1),
      ('diamond-bar-council-district-2', 0),
      ('diamond-bar-council-district-3', 1),
      ('diamond-bar-council-district-4', 1),
      ('diamond-bar-council-district-5', 0),
      ('claremont-council-district-1', 0),
      ('claremont-council-district-2', 1),
      ('claremont-council-district-3', 1),
      ('claremont-council-district-4', 1),
      ('claremont-council-district-5', 0),
      ('la-verne-council-district-1', 1),
      ('la-verne-council-district-2', 0),
      ('la-verne-council-district-3', 1),
      ('la-verne-council-district-4', 1),
      ('la-verne-council-district-5', 0)
      ) AS a(geo_id, up) JOIN essentials.geofence_boundaries me ON me.geo_id = a.geo_id AND me.mtfcc = 'X0001') x
   WHERE x.hits <> x.up;
  IF n_dpoly <> 26 THEN RAISE EXCEPTION 'districts: % of 26 new district rows resolve to a polygon', n_dpoly; END IF;
  IF n_seatok <> 26 THEN RAISE EXCEPTION 'seats: % of 26 seats in place with their named holder', n_seatok; END IF;
  IF n_dbad <> 0 THEN RAISE EXCEPTION '% district row(s) without exactly one office', n_dbad; END IF;
  IF n_size <> 5 THEN RAISE EXCEPTION 'councils: % of 5 at their expected size', n_size; END IF;
  IF n_dleak <> 0 THEN RAISE EXCEPTION '% district(s) reach the wrong number of district races', n_dleak; END IF;
  SELECT count(*) INTO n_em FROM (VALUES ('04f794ba-abdd-4426-9196-3ae3fbbf1356'::uuid, '4a500ae5-3bdd-4a1d-897c-51ab28840489'::uuid), ('6e8154ec-3e92-421f-b6fd-d419f7ba54e6'::uuid, '407fcd6b-93ae-44e8-b400-c5545038332e'::uuid)) AS v(oid, pid)
    JOIN essentials.office_current_holder och ON och.office_id = v.oid AND och.politician_id = v.pid;
  IF n_em <> 2 THEN RAISE EXCEPTION 'El Monte: % of 2 clerk/treasurer seats held', n_em; END IF;
  RAISE NOTICE 'CA_0173 applied: % races, % candidates, % incumbents linked', n_races, n_cands, n_inc;
END $$;

COMMIT;
